  1	#!/usr/bin/env node
  2	
  3	import fs from "node:fs/promises";
  4	import path from "node:path";
  5	import process from "node:process";
  6	import { execSync, spawn } from "node:child_process";
  7	import readline from "node:readline";
  8	import minimist from "minimist";
  9	import pty from "node-pty";
 10	
 11	import xtermHeadless from "@xterm/headless";
 12	import { SerializeAddon } from "@xterm/addon-serialize";
 13	
 14	const { Terminal } = xtermHeadless;
 15	type TerminalType = InstanceType<typeof Terminal>;
 16	
 17	type Snapshot = {
 18	  id: string;
 19	  label: string;
 20	  ts: string;
 21	  cols: number;
 22	  rows: number;
 23	  ansi: string;
 24	  // Backward-compatible field: keeps previous behavior (viewport text).
 25	  plain: string;
 26	  // Visible screen content at snapshot time.
 27	  plainViewport?: string;
 28	  // Full active buffer content (scrollback + viewport).
 29	  plainAll?: string;
 30	  // Snapshot viewport origin in the active buffer.
 31	  viewportY?: number;
 32	  // Total active buffer length at snapshot time.
 33	  bufferLength?: number;
 34	  keysSinceLastSnapshot: string[];
 35	};
 36	
 37	function nowId() {
 38	  const d = new Date();
 39	  const pad = (n: number) => String(n).padStart(2, "0");
 40	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
 41	}
 42	
 43	function trimTrailingEmptyLines(lines: string[]) {
 44	  let end = lines.length;
 45	  while (end > 0 && lines[end - 1] === "") {
 46	    end -= 1;
 47	  }
 48	  return lines.slice(0, end);
 49	}
 50	
 51	function dumpPlainRange(term: TerminalType, startY: number, endYExclusive: number) {
 52	  const lines: string[] = [];
 53	  const buffer = term.buffer.active;
 54	  const start = Math.max(0, startY);
 55	  const end = Math.max(start, Math.min(endYExclusive, buffer.length));
 56	  for (let y = start; y < end; y++) {
 57	    const line = buffer.getLine(y);
 58	    lines.push(line ? line.translateToString(true) : "");
 59	  }
 60	  return trimTrailingEmptyLines(lines).join("\n");
 61	}
 62	
 63	function dumpPlainViewport(term: TerminalType) {
 64	  const buffer = term.buffer.active;
 65	  const viewportY = buffer.viewportY ?? buffer.baseY ?? 0;
 66	  return dumpPlainRange(term, viewportY, viewportY + term.rows);
 67	}
 68	
 69	function dumpPlainAll(term: TerminalType) {
 70	  const buffer = term.buffer.active;
 71	  return dumpPlainRange(term, 0, buffer.length);
 72	}
 73	
 74	async function ensureDir(p: string) {
 75	  await fs.mkdir(p, { recursive: true });
 76	}
 77	
 78	async function promptLabel(): Promise<string> {
 79	  // 完全退出 raw mode，使用正常的行输入
 80	  if (process.stdin.isTTY) {
 81	    process.stdin.setRawMode(false);
 82	  }
 83	  process.stdin.pause();
 84	  
 85	  // 使用 readline 来读取输入，更可靠
 86	  return new Promise<string>((resolve) => {
 87	    const rl = readline.createInterface({
 88	      input: process.stdin,
 89	      output: process.stdout,
 90	      terminal: true
 91	    });
 92	    
 93	    // 先输出换行，确保提示在新行
 94	    process.stdout.write('\r\n');
 95	    
 96	    rl.question('label> ', (answer: string) => {
 97	      rl.close();
 98	      // 恢复 raw mode
 99	      if (process.stdin.isTTY) {
100	        process.stdin.setRawMode(true);
101	      }
102	      process.stdin.resume();
103	      resolve(answer.trim() || "untitled");
104	    });
105	  });
106	}
107	
108	async function exportSpec(sessionDir: string) {
109	  const screensDir = path.join(sessionDir, "screens");
110	  const files = await fs.readdir(screensDir);
111	  const jsonFiles = files.filter((f: string) => f.endsWith(".json")).sort();
112	  
113	  const screens: Snapshot[] = [];
114	  for (const file of jsonFiles) {
115	    const content = await fs.readFile(path.join(screensDir, file), "utf8");
116	    screens.push(JSON.parse(content));
117	  }
118	
119	  let spec = "# Terminal UI Specification\n\n";
120	  spec += `Generated from session: ${path.basename(sessionDir)}\n\n`;
121	  spec += `Total screens: ${screens.length}\n\n`;
122	  spec += "---\n\n";
123	
124	  for (const screen of screens) {
125	    const plainViewport = screen.plainViewport ?? screen.plain ?? "";
126	    const plainAll = screen.plainAll ?? screen.plain ?? "";
127	    const hasAllBufferDiff = plainAll !== plainViewport;
128	
129	    spec += `## Screen: ${screen.id}_${screen.label}\n\n`;
130	    spec += `- **Timestamp**: ${screen.ts}\n`;
131	    spec += `- **Size**: ${screen.cols}x${screen.rows}\n`;
132	    if (typeof screen.viewportY === "number") {
133	      spec += `- **Viewport Y**: ${screen.viewportY}\n`;
134	    }
135	    if (typeof screen.bufferLength === "number") {
136	      spec += `- **Buffer Length**: ${screen.bufferLength}\n`;
137	    }
138	    spec += `- **Keys since last**: ${JSON.stringify(screen.keysSinceLastSnapshot)}\n\n`;
139	    
140	    spec += "### Plain Text (Viewport):\n\n";
141	    spec += "```txt\n";
142	    spec += plainViewport;
143	    spec += "\n```\n\n";
144	
145	    if (hasAllBufferDiff) {
146	      const base = `${screen.id}_${screen.label}`;
147	      spec += `- **All Buffer Text File**: \`screens/${base}.all.txt\`\n\n`;
148	    }
149	    
150	    spec += "### ANSI (with colors/styling):\n\n";
151	    spec += "```ansi\n";
152	    spec += screen.ansi;
153	    spec += "\n```\n\n";
154	    
155	    spec += "---\n\n";
156	  }
157	
158	  // Generate flows
159	  spec += "## Navigation Flows\n\n";
160	  for (let i = 0; i < screens.length - 1; i++) {
161	    const from = screens[i];
162	    const to = screens[i + 1];
163	    const keys = to.keysSinceLastSnapshot.map(k => {
164	      // 转义特殊字符以便阅读
165	      if (k === "\t") return "Tab";
166	      if (k === "\r" || k === "\n") return "Enter";
167	      if (k === "\x1b") return "Esc";
168	      if (k.length === 1 && k.charCodeAt(0) < 32) {
169	        return `Ctrl+${String.fromCharCode(k.charCodeAt(0) + 64)}`;
170	      }
171	      return JSON.stringify(k);
172	    }).join(" → ");
173	    spec += `- **${from.label}** → **${to.label}**: ${keys}\n`;
174	  }
175	
176	  const specPath = path.join(sessionDir, "spec.md");
177	  await fs.writeFile(specPath, spec, "utf8");
178	  process.stdout.write(`\n[spec] exported: ${specPath}\n`);
179	}
180	
181	async function main() {
182	  const argv = minimist(process.argv.slice(2), { "--": true });
183	  const cmdParts = argv["--"];
184	
185	  // 处理导出 spec 命令
186	  if (argv.export || argv.e) {
187	    const sessionPath = argv.export || argv.e;
188	    if (!sessionPath) {
189	      console.error("Usage: snapui --export <session-dir>");
190	      process.exit(1);
191	    }
192	    const sessionDir = path.resolve(sessionPath);
193	    await exportSpec(sessionDir);
194	    return;
195	  }
196	
197	  if (!cmdParts?.length) {
198	    console.error("Usage: snapui -- <cmd> [args...]");
199	    console.error("   or: snapui --export <session-dir>");
200	    process.exit(1);
201	  }
202	
203	  const sessionId = nowId();
204	  const outDir = path.resolve(process.cwd(), "snapshots", sessionId);
205	  const screensDir = path.join(outDir, "screens");
206	  await ensureDir(screensDir);
207	
208	  const cols = process.stdout.columns ?? 120;
209	  const rows = process.stdout.rows ?? 40;
210	
211	  // 1) spawn pty
212	  // Try to find command in PATH if not absolute path
213	  let cmdPath = cmdParts[0];
214	  if (!path.isAbsolute(cmdPath)) {
215	    try {
216	      const which = execSync(`which ${cmdPath}`, { encoding: "utf8" }).trim();
217	      if (which) {
218	        cmdPath = which;
219	      }
220	    } catch (e) {
221	      // Command not found in PATH, use as-is
222	    }
223	  }
224	
225	  // Spawn the command
226	  // For complex commands or binaries, we'll try direct spawn first
227	  let child: pty.IPty;
228	  try {
229	    child = pty.spawn(cmdPath, cmdParts.slice(1), {
230	      cols,
231	      rows,
232	      cwd: process.cwd(),
233	      env: { ...process.env, TERM: "xterm-256color" } as Record<string, string>,
234	      name: "xterm-256color",
235	    });
236	  } catch (error: any) {
237	    // If direct spawn fails, try through shell
238	    console.error(`Failed to spawn directly: ${error.message}`);
239	    console.error(`Trying through shell...`);
240	    const shell = process.env.SHELL || "/bin/zsh";
241	    const fullCmd = cmdParts.join(" ");
242	    child = pty.spawn(shell, ["-c", fullCmd], {
243	      cols,
244	      rows,
245	      cwd: process.cwd(),
246	      env: { ...process.env, TERM: "xterm-256color" } as Record<string, string>,
247	      name: "xterm-256color",
248	    });
249	  }
250	
251	  // 2) headless xterm
252	  const term = new Terminal({ cols, rows, allowProposedApi: true });
253	  const serializeAddon = new SerializeAddon();
254	  term.loadAddon(serializeAddon);
255	
256	  // 3) logging (keys + raw output events)
257	  const eventsPath = path.join(outDir, "events.jsonl");
258	  const appendEvent = async (obj: any) => {
259	    await fs.appendFile(eventsPath, JSON.stringify(obj) + "\n", "utf8");
260	  };
261	
262	  // key segment between snapshots
263	  let keyBuffer: string[] = [];
264	  let snapCounter = 0;
265	  let outputPaused = false; // 标志：是否暂停输出（等待输入时）
266	  let inputPaused = false; // 标志：是否暂停按键转发（等待输入 label 时）
267	
268	  // 4) pipe child output => xterm buffer AND stdout (so user can see it)
269	  const handleChildData = (data: string) => {
270	    // 如果输出被暂停（等待输入），只写入 buffer，不显示到终端
271	    if (outputPaused) {
272	      term.write(data); // 仍然写入 buffer 用于捕获
273	      void appendEvent({ 
274	        ts: new Date().toISOString(), 
275	        type: "pty.out", 
276	        bytes: Buffer.byteLength(data), 
277	        sample: data.slice(0, 120).toString() 
278	      });
279	      return;
280	    }
281	    
282	    // Write to xterm buffer for capturing
283	    term.write(data);
284	    // Also write to stdout so user can see the UI
285	    process.stdout.write(data);
286	    void appendEvent({ 
287	      ts: new Date().toISOString(), 
288	      type: "pty.out", 
289	      bytes: Buffer.byteLength(data), 
290	      sample: data.slice(0, 120).toString() 
291	    });
292	  };
293	  
294	  child.onData(handleChildData);
295	
296	  // 5) stdin raw -> child input (同时拦截 Ctrl+S / Ctrl+Q / Ctrl+E)
297	  if (process.stdin.isTTY) {
298	    process.stdin.setRawMode(true);
299	  }
300	  process.stdin.resume();
301	
302	  const takeSnapshot = async () => {
303	    // 等一下让 UI 稳定（避免抓到"正在重画"的瞬间）
304	    await new Promise((r) => setTimeout(r, 80));
305	
306	    // 自动生成 label，基于序号
307	    snapCounter += 1;
308	    const label = `snapshot_${String(snapCounter).padStart(3, "0")}`;
309	    
310	    const ansi = serializeAddon.serialize();
311	    const plainViewport = dumpPlainViewport(term);
312	    const plainAll = dumpPlainAll(term);
313	    const plain = plainViewport;
314	    const viewportY = term.buffer.active.viewportY ?? term.buffer.active.baseY ?? 0;
315	    const bufferLength = term.buffer.active.length;
316	    
317	    const id = String(snapCounter).padStart(4, "0");
318	    const base = `${id}_${label}`;
319	
320	    const snap: Snapshot = {
321	      id,
322	      label,
323	      ts: new Date().toISOString(),
324	      cols: term.cols,
325	      rows: term.rows,
326	      ansi,
327	      plain,
328	      plainViewport,
329	      plainAll,
330	      viewportY,
331	      bufferLength,
332	      keysSinceLastSnapshot: keyBuffer,
333	    };
334	
335	    await fs.writeFile(path.join(screensDir, `${base}.json`), JSON.stringify(snap, null, 2), "utf8");
336	    await fs.writeFile(path.join(screensDir, `${base}.txt`), plain, "utf8");
337	    await fs.writeFile(path.join(screensDir, `${base}.viewport.txt`), plainViewport, "utf8");
338	    await fs.writeFile(path.join(screensDir, `${base}.all.txt`), plainAll, "utf8");
339	
340	    await appendEvent({ 
341	      ts: snap.ts, 
342	      type: "snapshot", 
343	      id, 
344	      label, 
345	      keys: keyBuffer.length,
346	      viewportY,
347	      bufferLength
348	    });
349	    keyBuffer = [];
350	    process.stdout.write(`\n[snap] saved: ${base}\n`);
351	  };
352	
353	  process.stdin.on("data", (buf: Buffer) => {
354	    // 如果正在等待输入 label，不处理按键（除了 Ctrl+C）
355	    if (inputPaused) {
356	      // 只允许 Ctrl+C 退出
357	      if (buf.length === 1 && buf[0] === 0x03) {
358	        process.stdout.write("\n\n[snapui] Interrupted by Ctrl+C\n");
359	        void appendEvent({ ts: new Date().toISOString(), type: "interrupt" });
360	        child.kill();
361	        if (process.stdin.isTTY) {
362	          process.stdin.setRawMode(false);
363	        }
364	        process.exit(130);
365	      }
366	      // 其他按键在等待输入时忽略（readline 会处理）
367	      return;
368	    }
369	    
370	    // 首先处理 Ctrl+C (0x03) - 必须能够退出！
371	    if (buf.length === 1 && buf[0] === 0x03) {
372	      process.stdout.write("\n\n[snapui] Interrupted by Ctrl+C\n");
373	      void appendEvent({ ts: new Date().toISOString(), type: "interrupt" });
374	      child.kill();
375	      if (process.stdin.isTTY) {
376	        process.stdin.setRawMode(false);
377	      }
378	      process.exit(130); // Standard exit code for SIGINT
379	    }
380	    
381	    // 使用简单的单字符热键，更可靠
382	    // Control+] (0x1D) 快照, Control+\ (0x1C) 导出, Control+Q (0x11) 退出
383	    if (buf.length === 1) {
384	      if (buf[0] === 0x1D) { // Control+]
385	        void takeSnapshot();
386	        return;
387	      }
388	      if (buf[0] === 0x1C) { // Control+\
389	        void exportSpec(outDir);
390	        return;
391	      }
392	      if (buf[0] === 0x11) { // Control+Q
393	        void appendEvent({ ts: new Date().toISOString(), type: "quit" });
394	        child.kill();
395	        if (process.stdin.isTTY) {
396	          process.stdin.setRawMode(false);
397	        }
398	        process.exit(0);
399	      }
400	    }
401	    
402	    // 也支持 F5, F6, F7 (不同终端可能有不同的转义序列)
403	    const dataStr = buf.toString();
404	    // F5 可能的序列: \x1b[15~ 或 \x1bOP
405	    if (dataStr === '\x1b[15~' || dataStr === '\x1bOP') {
406	      void takeSnapshot();
407	      return;
408	    }
409	    // F6 可能的序列: \x1b[17~ 或 \x1bOQ
410	    if (dataStr === '\x1b[17~' || dataStr === '\x1bOQ') {
411	      void exportSpec(outDir);
412	      return;
413	    }
414	    // F7 可能的序列: \x1b[18~ 或 \x1bOR
415	    if (dataStr === '\x1b[18~' || dataStr === '\x1bOR') {
416	      void appendEvent({ ts: new Date().toISOString(), type: "quit" });
417	      child.kill();
418	      if (process.stdin.isTTY) {
419	        process.stdin.setRawMode(false);
420	      }
421	      process.exit(0);
422	    }
423	
424	    // 记录按键（用于 flows）
425	    keyBuffer.push(buf.toString("utf8"));
426	    void appendEvent({ ts: new Date().toISOString(), type: "key", key: buf.toString("utf8") });
427	
428	    // 透传给被采集程序
429	    child.write(buf.toString("utf8"));
430	  });
431	  
432	  // 也监听 SIGINT 信号（Ctrl+C）
433	  process.on('SIGINT', () => {
434	    process.stdout.write("\n\n[snapui] Interrupted by Ctrl+C\n");
435	    void appendEvent({ ts: new Date().toISOString(), type: "interrupt" });
436	    child.kill();
437	    if (process.stdin.isTTY) {
438	      process.stdin.setRawMode(false);
439	    }
440	    process.exit(130);
441	  });
442	
443	  // session metadata
444	  await fs.writeFile(
445	    path.join(outDir, "session.json"),
446	    JSON.stringify(
447	      {
448	        ts: new Date().toISOString(),
449	        cmd: cmdParts,
450	        cols,
451	        rows,
452	      },
453	      null,
454	      2
455	    ),
456	    "utf8"
457	  );
458	
459	  // 显示使用提示
460	  process.stdout.write("\n[snapui] Started.\n");
461	  process.stdout.write("Hotkeys (推荐使用 Control 组合键):\n");
462	  process.stdout.write("  Control+]  - Take snapshot (最可靠)\n");
463	  process.stdout.write("  Control+\\  - Export spec.md\n");
464	  process.stdout.write("  Control+Q  - Quit\n");
465	  process.stdout.write("  Ctrl+C     - Force quit (emergency exit)\n");
466	  process.stdout.write("(F5/F6/F7 功能键也可用，但可能在某些终端不工作)\n\n");
467	}
468	
469	main().catch((e) => {
470	  console.error(e);
471	  process.exit(1);
472	});

  1	import { EVENTS, SAVE_LOCATIONS } from './constants.js';
  2	import { clamp } from './utils.js';
  3	
  4	export type HooksState =
  5		| { view: 'IDLE'; command: string }
  6		| { view: 'EVENT_LIST'; selectedIndex: number; scrollOffset: number }
  7		| { view: 'MATCHER_LIST'; selectedIndex: number }
  8		| { view: 'ADD_MATCHER'; inputText: string }
  9		| { view: 'ADD_HOOK'; matcherName: string; inputText: string }
 10		| { view: 'SAVE_HOOK'; matcherName: string; hookCommand: string; selectedIndex: number };
 11	
 12	export type HooksAction =
 13		| { type: 'SET_COMMAND'; value: string }
 14		| { type: 'SET_INPUT'; value: string }
 15		| { type: 'MOVE_CURSOR'; delta: number }
 16		| { type: 'SELECT_ITEM' }
 17		| { type: 'BACK' }
 18		| { type: 'RESET' };
 19	
 20	export const initialState: HooksState = { view: 'EVENT_LIST', selectedIndex: 0, scrollOffset: 0 };
 21	
 22	export function hooksReducer(state: HooksState, action: HooksAction): HooksState {
 23		switch (action.type) {
 24			case 'SET_COMMAND':
 25				if (state.view !== 'IDLE') return state;
 26				return { ...state, command: action.value };
 27	
 28			case 'SET_INPUT':
 29				if (state.view === 'ADD_MATCHER') {
 30					return { ...state, inputText: action.value };
 31				}
 32				if (state.view === 'ADD_HOOK') {
 33					return { ...state, inputText: action.value };
 34				}
 35				return state;
 36	
 37			case 'MOVE_CURSOR':
 38				if (state.view === 'EVENT_LIST') {
 39					const nextIndex = clamp(state.selectedIndex + action.delta, 0, EVENTS.length - 1);
 40					let nextOffset = state.scrollOffset;
 41					if (nextIndex < nextOffset) {
 42						nextOffset = nextIndex;
 43					} else if (nextIndex >= nextOffset + 5) {
 44						nextOffset = nextIndex - 4;
 45					}
 46					return { ...state, selectedIndex: nextIndex, scrollOffset: nextOffset };
 47				}
 48				if (state.view === 'MATCHER_LIST') {
 49					// Only one item locally for now
 50					return state; 
 51				}
 52				if (state.view === 'SAVE_HOOK') {
 53					const nextIndex = clamp(state.selectedIndex + action.delta, 0, SAVE_LOCATIONS.length - 1);
 54					return { ...state, selectedIndex: nextIndex };
 55				}
 56				return state;
 57	
 58			case 'SELECT_ITEM':
 59				if (state.view === 'IDLE') {
 60					if (state.command.trim() === '/hooks') {
 61						return { view: 'EVENT_LIST', selectedIndex: 0, scrollOffset: 0 };
 62					}
 63					return { ...state, command: '' };
 64				}
 65				if (state.view === 'EVENT_LIST') {
 66					return { view: 'MATCHER_LIST', selectedIndex: 0 };
 67				}
 68				if (state.view === 'MATCHER_LIST') {
 69					return { view: 'ADD_MATCHER', inputText: '' };
 70				}
 71				if (state.view === 'ADD_MATCHER') {
 72					return { view: 'ADD_HOOK', matcherName: state.inputText, inputText: '' };
 73				}
 74				if (state.view === 'ADD_HOOK') {
 75					return { 
 76						view: 'SAVE_HOOK', 
 77						matcherName: state.matcherName, 
 78						hookCommand: state.inputText, 
 79						selectedIndex: 0 
 80					};
 81				}
 82				if (state.view === 'SAVE_HOOK') {
 83					// Save action would happen here or be triggered by side effect
 84					// For now returns to IDLE as per original flow
 85					return { view: 'IDLE', command: '' };
 86				}
 87				return state;
 88	
 89			case 'BACK':
 90				if (state.view === 'EVENT_LIST') return { view: 'IDLE', command: '' };
 91				if (state.view === 'MATCHER_LIST') return { view: 'EVENT_LIST', selectedIndex: 0, scrollOffset: 0 };
 92				if (state.view === 'ADD_MATCHER') return { view: 'MATCHER_LIST', selectedIndex: 0 };
 93				if (state.view === 'ADD_HOOK') return { view: 'MATCHER_LIST', selectedIndex: 0 };
 94				if (state.view === 'SAVE_HOOK') return { view: 'ADD_HOOK', matcherName: state.matcherName, inputText: state.hookCommand };
 95				return state;
 96	
 97			case 'RESET':
 98				return { view: 'IDLE', command: '' };
 99	
100			default:
101				return state;
102		}
103	}

 1	import React, { useReducer, useEffect, useState } from 'react';
 2	import { Box, Text, useInput, useApp } from 'ink';
 3	import { hooksReducer, initialState } from './reducer.js';
 4	import { EventListView, MatcherListView, AddMatcherView, AddHookView, SaveHookView } from './ui.js';
 5	
 6	export function HooksDialog() {
 7		const { exit } = useApp();
 8		const [state, dispatch] = useReducer(hooksReducer, initialState);
 9	    const stateRef = React.useRef(state);
10	    stateRef.current = state;
11		
12		// Separate state for message logs if needed, or keep it local
13		// The original had `lastMessages` but it was only used on exit.
14	
15		useInput((input, key) => {
16	        const s = stateRef.current;
17	
18			if (s.view === 'ADD_MATCHER' || s.view === 'ADD_HOOK') {
19				if (key.return) {
20					dispatch({ type: 'SELECT_ITEM' });
21				} else if (key.backspace) {
22					dispatch({ type: 'SET_INPUT', value: s.inputText.slice(0, -1) });
23				} else if (key.escape) {
24					dispatch({ type: 'BACK' });
25				} else {
26					dispatch({ type: 'SET_INPUT', value: s.inputText + input });
27				}
28				return;
29			}
30	
31			// Navigation views
32			if (key.escape) {
33				if (s.view === 'EVENT_LIST') {
34					exit();
35				} else {
36					dispatch({ type: 'BACK' });
37				}
38				return;
39			}
40	
41			if (key.upArrow) {
42				dispatch({ type: 'MOVE_CURSOR', delta: -1 });
43			}
44	
45			if (key.downArrow) {
46				dispatch({ type: 'MOVE_CURSOR', delta: 1 });
47			}
48	
49			if (key.return) {
50				if (s.view === 'SAVE_HOOK') {
51					// On save completion
52					exit();
53				} else {
54					dispatch({ type: 'SELECT_ITEM' });
55				}
56			}
57		});
58	
59		// Render based on state
60		if (state.view === 'EVENT_LIST') {
61			return <EventListView selectedIndex={state.selectedIndex} scrollOffset={state.scrollOffset} />;
62		}
63		if (state.view === 'MATCHER_LIST') {
64			return <MatcherListView />;
65		}
66		if (state.view === 'ADD_MATCHER') {
67			return <AddMatcherView inputText={state.inputText} />;
68		}
69		if (state.view === 'ADD_HOOK') {
70			return <AddHookView matcherName={state.matcherName} inputText={state.inputText} />;
71		}
72		if (state.view === 'SAVE_HOOK') {
73			return <SaveHookView matcherName={state.matcherName} hookCommand={state.hookCommand} selectedIndex={state.selectedIndex} />;
74		}
75	
76		return null; 
77	}

