  1	import { EVENTS, SAVE_LOCATIONS } from './constants.js';
  2	import { clamp } from './utils.js';
  3	
  4	export type HooksState =
  5		| { view: 'IDLE'; command: string }
  6		| { view: 'EVENT_LIST'; selectedIndex: number; scrollOffset: number }
  7		| { view: 'MATCHER_LIST'; selectedIndex: number }
  8		| { view: 'ADD_MATCHER'; inputText: string }
  9		| { view: 'ADD_HOOK'; matcherName: string; inputText: string }
 10		| { view: 'SAVE_HOOK'; matcherName: string; hookCommand: string; selectedIndex: number };
 11	
 12	export type HooksAction =
 13		| { type: 'SET_COMMAND'; value: string }
 14		| { type: 'SET_INPUT'; value: string }
 15		| { type: 'MOVE_CURSOR'; delta: number }
 16		| { type: 'SELECT_ITEM' }
 17		| { type: 'BACK' }
 18		| { type: 'RESET' };
 19	
 20	export const initialState: HooksState = { view: 'EVENT_LIST', selectedIndex: 0, scrollOffset: 0 };
 21	
 22	export function hooksReducer(state: HooksState, action: HooksAction): HooksState {
 23		switch (action.type) {
 24			case 'SET_COMMAND':
 25				if (state.view !== 'IDLE') return state;
 26				return { ...state, command: action.value };
 27	
 28			case 'SET_INPUT':
 29				if (state.view === 'ADD_MATCHER') {
 30					return { ...state, inputText: action.value };
 31				}
 32				if (state.view === 'ADD_HOOK') {
 33					return { ...state, inputText: action.value };
 34				}
 35				return state;
 36	
 37			case 'MOVE_CURSOR':
 38				if (state.view === 'EVENT_LIST') {
 39					const nextIndex = clamp(state.selectedIndex + action.delta, 0, EVENTS.length - 1);
 40					let nextOffset = state.scrollOffset;
 41					if (nextIndex < nextOffset) {
 42						nextOffset = nextIndex;
 43					} else if (nextIndex >= nextOffset + 5) {
 44						nextOffset = nextIndex - 4;
 45					}
 46					return { ...state, selectedIndex: nextIndex, scrollOffset: nextOffset };
 47				}
 48				if (state.view === 'MATCHER_LIST') {
 49					// Only one item locally for now
 50					return state; 
 51				}
 52				if (state.view === 'SAVE_HOOK') {
 53					const nextIndex = clamp(state.selectedIndex + action.delta, 0, SAVE_LOCATIONS.length - 1);
 54					return { ...state, selectedIndex: nextIndex };
 55				}
 56				return state;
 57	
 58			case 'SELECT_ITEM':
 59				if (state.view === 'IDLE') {
 60					if (state.command.trim() === '/hooks') {
 61						return { view: 'EVENT_LIST', selectedIndex: 0, scrollOffset: 0 };
 62					}
 63					return { ...state, command: '' };
 64				}
 65				if (state.view === 'EVENT_LIST') {
 66					return { view: 'MATCHER_LIST', selectedIndex: 0 };
 67				}
 68				if (state.view === 'MATCHER_LIST') {
 69					return { view: 'ADD_MATCHER', inputText: '' };
 70				}
 71				if (state.view === 'ADD_MATCHER') {
 72					return { view: 'ADD_HOOK', matcherName: state.inputText, inputText: '' };
 73				}
 74				if (state.view === 'ADD_HOOK') {
 75					return { 
 76						view: 'SAVE_HOOK', 
 77						matcherName: state.matcherName, 
 78						hookCommand: state.inputText, 
 79						selectedIndex: 0 
 80					};
 81				}
 82				if (state.view === 'SAVE_HOOK') {
 83					// Save action would happen here or be triggered by side effect
 84					// For now returns to IDLE as per original flow
 85					return { view: 'IDLE', command: '' };
 86				}
 87				return state;
 88	
 89			case 'BACK':
 90				if (state.view === 'EVENT_LIST') return { view: 'IDLE', command: '' };
 91				if (state.view === 'MATCHER_LIST') return { view: 'EVENT_LIST', selectedIndex: 0, scrollOffset: 0 };
 92				if (state.view === 'ADD_MATCHER') return { view: 'MATCHER_LIST', selectedIndex: 0 };
 93				if (state.view === 'ADD_HOOK') return { view: 'MATCHER_LIST', selectedIndex: 0 };
 94				if (state.view === 'SAVE_HOOK') return { view: 'ADD_HOOK', matcherName: state.matcherName, inputText: state.hookCommand };
 95				return state;
 96	
 97			case 'RESET':
 98				return { view: 'IDLE', command: '' };
 99	
100			default:
101				return state;
102		}
103	}

